add('student_home_screen.dart','الرئيسية · سكن الطلاب','Student housing home',link('مجموعات السكن','housing_groups_screen.dart','secondary wide')+form(select('الجامعة أو الحرم','campus',['الحرم المختار · مثال'])+select('المدينة','city',['القاهرة','الجيزة'])+select('نطاق الإيجار','scope',['العقار بالكامل','غرفة','سرير'])+'<div class="field-pair">'+f('أقل ميزانية','minBudget','3000','number')+f('أعلى ميزانية','maxBudget','4000','number')+'</div><p class="small">الميزانية شهرية للفرد في البحث المستقل.</p>'+dates(),'معاينة البحث','student-search')+link('أدوات الخطة الدراسية','student_hub_screen.dart','secondary wide'),
 'Independent student search works without academic plan/group. Student context, campus, city, rental scope, monthly budget and optional dates preserved; group variant adds people and per-person/whole-group basis. Existing continuation/session draft and visit banner retained; valid availability searches still recheck server.',kind='form',back='tenant_home_screen.dart',hero=('سكن مناسب،<br>لأيام دراستك.','ابحث بالجامعة والميزانية والفترة.','سكن الطلاب'),refs=['S05','S07'],variants={'group-search':v(intro('بحث لمجموعتكم.','حددوا معنى الميزانية وعدد المشاركين.')+form(f('الأفراد','occupants','3','number')+select('أساس الميزانية','budgetBasis',['للفرد','للمجموعة كلها'])+f('أقل ميزانية','minBudget','9000','number')+f('أعلى ميزانية','maxBudget','12000','number')+dates(),'معاينة بحث المجموعة','student-search'))})
add('student_hub_screen.dart','أدوات السكن الدراسي','Student planning hub',intro('خطتك اختيارية، وخطوتك واضحة.','ابحث عن سكن مستقل أو نظّم خطة مع مجموعتك.')+link('ابحث عن سكن بدون خطة','student_home_screen.dart','primary wide')+student_plan()+section('خطتك الحالية',row('مراجعة موافقتي','المتطلبات والبيانات المختارة',to=go('student_consent_screen.dart'),symbol='shield')+row('ترتيبات المعيشة','الهدوء والتنظيف والدراسة',to=go('student_arrangements_screen.dart'),symbol='building')+row('سجل الخطة','النسخ والمتطلبات',to=go('student_history_screen.dart'),symbol='file'))+section('إيجارك ومشاركتك',row('ملخصات الإيجار','مشاركة محدودة باختيارك',to=go('rental_summaries_screen.dart'),symbol='file')+row('إبلاغ عن مشكلة البداية','خاص بإيجارك وخطتك',to=go('student_check_in_screen.dart'),symbol='help')),
 'StudentRentalEntry remains usable independently of planning gate. Optional personal/family planning, group-context plans and shared-with-me separated. Plans have blockers/revisions; planning unavailable must not hide independent rental/search. No compulsory family sharing.',kind='hub',back='student_home_screen.dart',states=['unavailable'],variants={'unavailable':v(intro('التخطيط غير متاح حاليًا.','تقدر تكمل البحث عن سكن بدون خطة.',True,'help')+link('البحث عن سكن','student_home_screen.dart','primary wide')+note('التخطيط ومشاركة الأسرة اختيارات مستقلة.'))})

assert len(SCREENS)==60,(len(SCREENS),set(BYFILE)-{Path(s['source']).name for s in SCREENS})
assert {s['source'] for s in SCREENS}=={r['source'] for r in AUDIT}

# Review states preserve native distinctions; they are not extra counted screens.
for s in SCREENS:
    title=s['name'];body=s['content'];foot=s['footer'];variants=s['variants']
    variants.setdefault('loading',v('<div class="loading-sample" aria-label="جار التحميل">'+''.join('<div class="skeleton"></div>' for _ in range(5))+'<p>جار تحميل البيانات…</p></div>'))
    if s['kind'] in ['form','action','payment','signing']:
        variants.setdefault('error',v(note('تعذّر إكمال الخطوة. بياناتك محفوظة في المعاينة؛ راجعها وحاول مرة أخرى.','error','help')+body,foot))
        blocked='<fieldset disabled class="batch-blocked">'+body+'</fieldset>'
        variants.setdefault('saving',v(note('جار تنفيذ الخطوة. لا تكرر الإرسال.','info','clock')+blocked))
        variants.setdefault('unknown-outcome',v(note('لم تتأكد نتيجة العملية. راجع المحاولة الأصلية قبل أي إرسال جديد.','warning','clock')+blocked,footer('مراجعة العملية الأصلية','batch-recover')))
    else:
        variants.setdefault('error',v(intro('تعذّر تحميل البيانات.','راجع الاتصال وحاول من جديد.',True,'help')+button('إعادة المحاولة',action='reset-state',kind='primary wide')))
        variants.setdefault('stale',v(note('هذه آخر بيانات معروضة. حدّثها قبل اتخاذ أي إجراء.','warning','clock')+panel('<h3>'+title+'</h3><p class="small">النسخة الحالية تحتاج مراجعة من جديد.</p>')+button('تحديث البيانات',action='reset-state',kind='primary wide')))
        variants.setdefault('restricted',v(intro('الإجراء غير متاح حاليًا.','الصلاحيات والحالة الحالية تحددان ما يمكنك متابعته.',True,'lock')+button('مراجعة الحالة',action='reset-state',kind='secondary wide')))
    if 'empty' in s['requiredStates']:
        variants.setdefault('empty',v(intro('لسه مفيش بيانات هنا.','هتظهر البيانات المتاحة لهذا الحساب في المكان ده.',True,'file')+button('تحديث',action='reset-state',kind='secondary wide')))
    for name,copy in {'resolved':'تم إغلاق الاعتراض في هذا المثال؛ راجع نص النتيجة من السجل.','disputed':'هناك بند محل اعتراض؛ لم تعتمد النتيجة المالية بعد.','revoked':'تم إلغاء المشاركة؛ الملخص غير متاح للمستلم في هذه الحالة.','waiting':'تنتظر هذه الخطوة شروط الإتاحة أو المراجعة؛ ليست نتيجة نهائية.','limited-sample':'عدد التجارب قليل؛ اقرأ النتائج في سياق حجم العينة.','archived':'سجل مؤرشف للقراءة فقط، لا يمثل الحالة الحالية.'}.items():
        if name in s['requiredStates']:
            variants.setdefault(name,v(intro(copy,'حالة توضيحية للمراجعة.',True,'file')+note('النتيجة الفعلية تعتمد على السجل والصلاحيات الحالية.')))
    if 'stale' in s['requiredStates']:
        variants.setdefault('stale',v(intro('النسخة تحتاج تحديثًا.','راجع بيانات الطلب الحالية قبل الرد.',True,'clock')+button('تحميل النسخة الحالية',action='reset-state',kind='primary wide')))
    for state in s['requiredStates']:
        if state in variants or state in ['dirty','invalid']:continue
        if state in ['permission-denied','unsupported','policy-unsupported','unavailable','signing-unavailable','delivery-unavailable']:
            variants[state]=v(intro('الخطوة غير متاحة حاليًا.','راجع الإذن أو إتاحة الخدمة قبل المتابعة.',True,'help')+button('مراجعة الحالة',action='reset-state',kind='secondary wide'))
        elif state in ['conflict','revision-changed','source-changed','inventory-changed','quote-changed','criteria-review']:
            variants[state]=v(note('التفاصيل أو النسخة اتغيّرت. راجع البيانات الحالية قبل تأكيد قرارك.','warning','file')+panel('<h3>'+title+'</h3><p class="small">لا تستخدم النسخة السابقة لإرسال إجراء جديد.</p>')+button('تحميل النسخة الحالية',action='reset-state',kind='primary wide'))
        elif state in ['expired','session-ended','self-action-blocked','read-only','legacy-read-only','unsafe']:
            wording={'expired':'انتهت صلاحية هذه الخطوة.','session-ended':'انتهت الجلسة.','self-action-blocked':'لا يمكن تنفيذ الإجراء على حسابك نفسه.','read-only':'هذه النسخة للقراءة فقط.','legacy-read-only':'سجل سابق للقراءة فقط.','unsafe':'المرفق غير متاح للعرض.'}[state]
            variants[state]=v(intro(wording,'راجع الحالة الحالية من المصدر قبل المتابعة.',True,'lock')+button('مراجعة الحالة',action='reset-state',kind='secondary wide'))
        elif state in ['processing','scanning']:
            variants[state]=v(intro('الخطوة قيد المعالجة.','البيانات ليست جاهزة للاعتماد بعد.',True,'clock')+'<div class="coverage-meter"><span style="width:55%"></span></div>'+button('مراجعة الحالة',action='reset-state',kind='secondary wide'))
        elif state in ['paid','signed','accepted']:
            variants[state]=v(intro({'paid':'تحصيل مؤكّد · مثال','signed':'نسخة موقّعة · مثال','accepted':'مقبولة · مثال'}[state],'حالة توضيحية؛ النتيجة الفعلية تعتمد على السجل المعتمد.',True,'check')+summary([('المرجع','مثال توضيحي'),('السجل','الحالة مؤكدة في هذا المثال فقط')]))
        elif state in ['fulfillment-pending','extension-pending','grace','chargeback','availability-unknown','partial-error','no-baseline','evidence-missing','no-selectable-output','cancelled','delivery-unknown']:
            copy={'fulfillment-pending':'تمت مراجعة الدفع، والتفعيل لم يتأكد بعد.','extension-pending':'طلب المهلة في انتظار المراجعة.','grace':'فترة سماح حسب سجل الاشتراك.','chargeback':'العملية محل مراجعة اعتراض مالي.','availability-unknown':'إتاحة العقار لم تتأكد بعد.','partial-error':'بعض الاختيارات لم يكتمل تحميلها.','no-baseline':'لا يوجد تقرير دخول مرجعي متاح.','evidence-missing':'أعد اختيار المرفقات المطلوبة قبل المتابعة.','no-selectable-output':'لا توجد مخرجات جاهزة للاختيار.','cancelled':'تم إلغاء مهمة البحث في هذا المثال.','delivery-unknown':'حالة تسليم الرسالة غير مؤكدة.'}[state]
            variants[state]=v(note(copy,'warning','clock')+panel('<h3>'+title+'</h3><p class="small">راجع التفاصيل المطلوبة قبل أي إجراء جديد.</p>')+button('مراجعة الحالة',action='reset-state',kind='secondary wide'))
    for missing in s['requiredStates']:
        if missing in variants or missing in ['dirty','invalid']:continue
        message={'restricted':'هذه الخطوة غير متاحة لصلاحيات الحساب الحالية.','unknown-outcome':'النتيجة غير مؤكدة. راجع السجل الأصلي قبل متابعة أي إجراء.'}.get(missing,'راجع الحالة الحالية قبل المتابعة.')
        variants[missing]=v(intro(message,'حالة توضيحية للمراجعة.',True,'lock')+button('مراجعة الحالة',action='reset-state',kind='secondary wide'))
    if Path(s['source']).name in ['rental_refund_detail_screen.dart','rental_payout_detail_screen.dart']:
        label='تم رد المبلغ · مثال' if 'refund' in s['source'] else 'اكتمل صرف المستحق · مثال'
        variants['paid']=v(intro(label,'حالة توضيحية من سجل العملية، وليست تحويلًا تنفذه المعاينة.',True,'check')+summary([('الحالة','مؤكدة في هذا المثال فقط'),('الإثبات','من سجل العملية المعتمد')]))
    # All rendered states are declared separately from additional native-only states.
    s['renderedStatePolicy']='Primary mockup plus explicitly labelled local review variants. Native dirty/invalid validation uses the form, not a separate counted screen.'

for number in range(8,11):
    batch=sorted([s for s in SCREENS if s['sprint']==number],key=lambda s:int(s['id'][1:]))
    assert len(batch)==20
    out=HERE/f'sprint-{number:02}'
    render(batch,number,out,(HERE/'sprint02.css').read_text()+'\n'+(HERE/'batch03_07.css').read_text()+'\n'+(HERE/'batch08_10.css').read_text(),(HERE/'batch08_10.js').read_text())
    docs=[f'# Sprint {number} — {batch[0]["id"]}–{batch[-1]["id"]}','','This sprint belongs to the authorized three-sprint batch (8–10). Stop after Sprint 10 for user review. No Flutter or API behavior changes.','','## Visual authority','','Original S01–S20, Readex/Plex type, pine/paper tokens, original control/card proportions and selective signature headers. All data, dates, balances, model previews and messages are illustrative. Maps/capture/provider/signature prototypes never use real device services or external APIs.','','## Source audit','','Every primary file and dependency below was inspected from the sibling `sokoun` checkout. `../batch-08-10-source-audit.json` records source hashes, label keys, commands and guards. A screen count represents a distinct source destination; its data/permission/provider variants do not inflate the count.','','## Common contract','','Freshness, role/capability, source revision, command identity and uncertain-write recovery remain authoritative. Private data stays scoped to session/workspace. Prototype confirmations only demonstrate intent: they do not assert payment, publication, signatures, consent for other users, refunds, occupancy or liability. A readonly or stale variant must not contain a mutating control.','','## Screen audit','']
    for s in batch:
        docs += [f'<a id="{s["id"].lower()}"></a>',f'### {s["id"]} — {s["english"]}','',f'Source: `{s["source"]}`','',s['behavior'],'','Original visual references: '+', '.join(s['visualReference'])+'.','','Required implementation states: '+', '.join(s['requiredStates'])+'.','','Rendered review variants: '+', '.join(s['variants'])+'.','','Dependencies: '+', '.join('`'+d['source']+'`' for d in s['dependencies'])+'.','']
    (out/'AUDIT.md').write_text('\n'.join(docs)+'\n')
    (out/'README.md').write_text(f'# Sprint {number} — {batch[0]["id"]}–{batch[-1]["id"]}\n\n[Open the 20 mockups](index.html) · [All screens](../../index.html) · [Behavior audit](AUDIT.md)\n\nPart of the three-sprint batch 8–10. Light/Dark/System, source-linked manifests, local workflow states and image exports. All data and actions are illustrative. Native device, API, provider and permission checks remain required during implementation.\n\nReview all three sprints before proceeding to Sprint 11.\n')
    print(f'Built Sprint {number}: {batch[0]["id"]}–{batch[-1]["id"]}, 20 screens')
import runpy
runpy.run_path(str(BASE/'build_gallery.py'),run_name='__main__')
